  it('rejects invalid payloads with 400', async () => {
    const res1 = await request(app)
      .post('/api/v1/bookmarks')
      .send({ title: 'No URL provided' });

    expect(res1.status).toBe(400);

    const res2 = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 123 });

    expect(res2.status).toBe(400);

    const res3 = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags: 'not-an-array' });

    expect(res3.status).toBe(400);
  });

  it('rejects invalid URL format', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'not-a-valid-url' });

    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error', 'Validation failed');
  });

  it('rejects title longer than 200 characters', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com',
        title: 'a'.repeat(201),
      });

    expect(res.status).toBe(400);
  });

  it('accepts title up to 200 characters', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com',
        title: 'a'.repeat(200),
      });

    expect(res.status).toBe(201);
  });

  it('rejects more than 10 tags', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com',
        tags: Array.from({ length: 11 }, (_, i) => `tag-${i}`),
      });

    expect(res.status).toBe(400);
  });

  it('rejects a tag longer than 50 characters', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com',
        tags: ['valid', 'b'.repeat(51)],
      });

    expect(res.status).toBe(400);
  });
});

import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export class BookmarkService {
  private readonly storage = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };
    this.storage.set(id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.storage.get(id);
  }

  getAll(): Bookmark[] {
    return Array.from(this.storage.values());
  }

  delete(id: string): boolean {
    return this.storage.delete(id);
  }

  clear(): void {
    this.storage.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import {
  type Bookmark,
  type CreateBookmarkInput,
  bookmarkService,
} from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url(),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type { Bookmark, CreateBookmarkInput };

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response): void => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.issues,
    });
    return;
  }

  const validData: CreateBookmarkInput = result.data;
  const newBookmark = bookmarkService.create(validData);

  res.status(201).json(newBookmark);
});

export default bookmarksRouter;

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService } from '../src/services/bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  it('creates and retrieves a bookmark by UUID', () => {
    const bookmark = service.create({
      url: 'https://example.com',
      title: 'Example',
      tags: ['test'],
    });

    expect(bookmark.id).toBeDefined();
    expect(bookmark.url).toBe('https://example.com');
    expect(bookmark.title).toBe('Example');
    expect(bookmark.tags).toEqual(['test']);
    expect(bookmark.createdAt).toBeDefined();

    const retrieved = service.getById(bookmark.id);
    expect(retrieved).toEqual(bookmark);
  });

  it('lists all bookmarks', () => {
    expect(service.getAll()).toHaveLength(0);

    service.create({ url: 'https://a.com' });
    service.create({ url: 'https://b.com' });

    expect(service.getAll()).toHaveLength(2);
  });

  it('deletes a bookmark by UUID', () => {
    const bookmark = service.create({ url: 'https://example.com' });
    expect(service.delete(bookmark.id)).toBe(true);
    expect(service.getById(bookmark.id)).toBeUndefined();
    expect(service.delete('non-existent')).toBe(false);
  });

  it('clears all bookmarks', () => {
    service.create({ url: 'https://example.com' });
    service.clear();
    expect(service.getAll()).toHaveLength(0);
  });
});

