import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

describe('POST /api/v1/bookmarks', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  it('creates a bookmark with only required fields and returns 201 with id and createdAt', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com' });

    expect(res.status).toBe(201);
    expect(res.body).toHaveProperty('id');
    expect(res.body.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    );
    expect(res.body.url).toBe('https://example.com');
    expect(res.body).toHaveProperty('createdAt');
    expect(new Date(res.body.createdAt).toISOString()).toBe(res.body.createdAt);

