Added the `GET /api/v1/bookmarks` endpoint to `src/routes/bookmarks.ts`:

### Route Implementation
```ts
bookmarksRouter.get('/', (_req: Request, res: Response): void => {
  const bookmarks = bookmarkService.getAll();
  res.status(200).json(bookmarks);
});
```

### Behavior
- Retrieves all stored bookmarks from `bookmarkService.getAll()`.
- Returns HTTP `200 OK` with an array of bookmarks, sorted by `createdAt` descending (newest first).
- Returns `[]` when no bookmarks have been created.

### Tests & Verification
- Added tests in `tests/bookmarks.test.ts` covering both empty state and sorted listing.
- All 42 tests pass (`vitest run`).
- Strict TypeScript verification (`tsc --noEmit`) passes with zero errors and no usage of `any`.

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  type Bookmark,
  type CreateBookmarkInput,
  bookmarkService,
} from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type { Bookmark, CreateBookmarkInput };

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (_req: Request, res: Response): void => {
  const bookmarks = bookmarkService.getAll();
  res.status(200).json(bookmarks);
});

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction): void => {
  try {
    const body: unknown = req.body;
    const validData = createBookmarkSchema.parse(body);
    const newBookmark = bookmarkService.create(validData);
    res.status(201).json(newBookmark);
  } catch (err: unknown) {
    next(err);
  }
});

export default bookmarksRouter;

