Pagination has been added to `GET /api/v1/bookmarks`:

### 1. Service Layer (`src/services/bookmark-service.ts`)
- Defined `PaginatedResult<T>` interface:
  ```ts
  export interface PaginatedResult<T> {
    data: T[];
    pagination: {
      page: number;
      limit: number;
      total: number;
      totalPages: number;
    };
  }
  ```
- Implemented `getPaginated(page: number, limit: number)` on `BookmarkService`, which slices the sorted bookmarks and computes total items and total pages.

### 2. Route Implementation (`src/routes/bookmarks.ts`)
- Updated `GET /` to parse and bound query parameters:
  - `page`: defaults to `1` (minimum `1`).
  - `limit`: defaults to `20` (capped between `1` and `100`).
- Returns HTTP 200 with `{ data: Bookmark[], pagination: { page, limit, total, totalPages } }`.

### 3. Tests & Verification
- Updated test suites in `tests/bookmarks.test.ts` and `tests/bookmarks.integration.test.ts` for the paginated structure and custom query parameters.
- All 52 tests pass (`vitest run`).
- `npm run typecheck` passes with zero errors under TypeScript strict mode (`strict: true`) with no `any` types.

import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly storage = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    for (const bookmark of this.storage.values()) {
      if (bookmark.url === input.url) {
