    expect(res.body.url).toBe('https://example.com/original');
    expect(res.body.title).toBe('Updated Title');
    expect(res.body.tags).toEqual(['updated', 'tags']);
    expect(res.body.createdAt).toBe(created.body.createdAt);
  });

  it('rejects attempt to modify url with 422', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com/immutable' });

    const res = await request(app)
      .patch(`/api/v1/bookmarks/${created.body.id}`)
      .send({ url: 'https://example.com/modified' });

    expect(res.status).toBe(422);
    expect(res.body).toHaveProperty('error', 'Validation failed');
  });

  it('returns 404 when updating non-existent bookmark', async () => {
    const res = await request(app)
      .patch('/api/v1/bookmarks/non-existent-id')
      .send({ title: 'New Title' });

