  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.issues,
    });
    return;
  }

  res.status(201).json({
    url: result.data.url,
    title: result.data.title,
    tags: result.data.tags,
  });
});

