    res.status(400).json({
      error: 'Invalid JSON payload',
    });
    return;
  }

  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation error',
      details: err.issues,
      errors: err.issues,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal Server Error',
