    it('should partially update title and tags while preserving id, url, and createdAt', () => {
      const bookmark = service.create({
        url: 'https://update-service.com',
        title: 'Old Title',
        tags: ['old'],
      });

      const updated = service.update(bookmark.id, {
        title: 'New Title',
        tags: ['new-tag-1', 'new-tag-2'],
      });

      expect(updated).toBeDefined();
      expect(updated?.id).toBe(bookmark.id);
      expect(updated?.url).toBe(bookmark.url);
      expect(updated?.createdAt).toBe(bookmark.createdAt);
      expect(updated?.title).toBe('New Title');
      expect(updated?.tags).toEqual(['new-tag-1', 'new-tag-2']);

      const retrieved = service.getById(bookmark.id);
      expect(retrieved).toEqual(updated);
    });

    it('should update title only and retain existing tags', () => {
      const bookmark = service.create({
        url: 'https://update-title-only.com',
        title: 'Original',
        tags: ['retain-me'],
      });

      const updated = service.update(bookmark.id, { title: 'Updated Only' });

      expect(updated?.title).toBe('Updated Only');
      expect(updated?.tags).toEqual(['retain-me']);
    });

    it('should return undefined when updating a non-existent id', () => {
      const result = service.update('non-existent-uuid', { title: 'Ghost' });
      expect(result).toBeUndefined();
    });
  });
});

